import{_ as r,y as s,a,o as i,a2 as t,D as n}from"./chunks/framework.DCcmcJcL.js";const f=JSON.parse('{"title":"GDPR","description":"","frontmatter":{},"headers":[],"relativePath":"configure/gdpr.md","filePath":"configure/gdpr.md","lastUpdated":1789441803000}'),g={name:"configure/gdpr.md"};function c(h,e,d,l,p,u){const o=s("ImagePopup");return i(),a("div",null,[e[0]||(e[0]=t('<h1 id="gdpr" tabindex="-1">GDPR <a class="header-anchor" href="#gdpr" aria-label="Permalink to &quot;GDPR&quot;">​</a></h1><p>Bagisto&#39;s GDPR (General Data Protection Regulation) features let customers ask you to update or delete the personal data you hold about them, ask customers to accept your terms before they create an account, and show a cookie notice on the storefront. Every setting on this screen is saved per channel and per language, so choose both at the top of the screen before you change anything, and repeat for each language your storefront offers.</p><h2 id="gdpr-compliance-settings" tabindex="-1">GDPR compliance settings <a class="header-anchor" href="#gdpr-compliance-settings" aria-label="Permalink to &quot;GDPR compliance settings&quot;">​</a></h2><p><strong>Enable GDPR</strong> is the main switch. The customer agreement and the cookie notice below only appear on the storefront while it is on. It is off by default.</p><ol><li>Go to <strong>Configure &gt;&gt; General &gt;&gt; GDPR</strong>.</li><li>In <strong>GDPR Compliance Settings</strong>, switch <strong>Enable GDPR</strong> on.</li><li>Click <strong>Save Configuration</strong>.</li></ol><p>When GDPR is on, customers find <strong>GDPR Requests</strong> in their account on the storefront, where they click <strong>Create Request</strong> to ask for their data to be updated or deleted. You handle the requests under <strong>Customers &gt;&gt; GDPR Data Requests</strong>; see <a href="./../customer/gdpr-data-requests.html">GDPR Data Requests</a>.</p><h2 id="gdpr-agreement" tabindex="-1">GDPR agreement <a class="header-anchor" href="#gdpr-agreement" aria-label="Permalink to &quot;GDPR agreement&quot;">​</a></h2><p>The customer agreement adds a checkbox that customers must tick on the sign-up form to create an account.</p><ol><li>Go to <strong>Configure &gt;&gt; General &gt;&gt; GDPR</strong>.</li><li>In <strong>GDPR Agreement</strong>, switch <strong>Enable Customer Agreement</strong> on. <strong>Agreement Checkbox Label</strong> and <strong>Agreement Content</strong> appear.</li><li>Enter the <strong>Agreement Checkbox Label</strong>, the sentence shown beside the checkbox, up to 255 characters. The default is <em>I agree with the terms and conditions.</em></li><li>Enter the <strong>Agreement Content</strong>, the full text of the agreement.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',9)),n(o,{src:"/images/configure/gdpr-settings.png",alt:"GDPR Compliance Settings and GDPR Agreement sections with both switches turned on"}),e[1]||(e[1]=t('<p>When <strong>Agreement Content</strong> has text, a <strong>Click Here</strong> link after the checkbox opens it. What shoppers see on the sign-up form is described in <a href="./../customer/customer-account.html#sign-up">Customer Account</a>.</p><h2 id="cookie-notice-settings" tabindex="-1">Cookie notice settings <a class="header-anchor" href="#cookie-notice-settings" aria-label="Permalink to &quot;Cookie notice settings&quot;">​</a></h2><p>The cookie notice tells shoppers about the cookies your storefront uses. It shows <strong>Accept</strong>, <strong>Reject</strong> and <strong>Learn More and Customize</strong> buttons, and a <strong>Privacy Policy</strong> link to your <code>privacy-policy</code> CMS page. The notice keeps appearing until the shopper clicks <strong>Accept</strong> or saves their choices on the cookie preferences page.</p><ol><li>Go to <strong>Configure &gt;&gt; General &gt;&gt; GDPR</strong>.</li><li>In <strong>Cookie Notice Settings</strong>, switch <strong>Enable Cookie Notice</strong> on. The other settings appear.</li><li>Change the settings described in the table.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',4)),n(o,{src:"/images/configure/gdpr-cookie-notice.png",alt:"Cookie Notice Settings section with the cookie notice turned on"}),e[2]||(e[2]=t('<table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Enable Cookie Notice</strong></td><td>Shows the notice on the storefront. It needs <strong>Enable GDPR</strong> on. Off by default.</td></tr><tr><td><strong>Cookie Block Display Position</strong></td><td>Where the notice appears: <strong>Bottom Left</strong> (the default), <strong>Bottom Right</strong>, <strong>Top Left</strong>, <strong>Top Right</strong> or <strong>Center</strong>.</td></tr><tr><td><strong>Static Block Identifier</strong></td><td>The heading at the top of the notice. The default is <strong>Cookie Block</strong>.</td></tr><tr><td><strong>Description</strong></td><td>The message shoppers read in the notice, up to 500 characters. The <strong>Privacy Policy</strong> link follows it.</td></tr></tbody></table><h2 id="manage-your-cookie-preferences" tabindex="-1">Manage your cookie preferences <a class="header-anchor" href="#manage-your-cookie-preferences" aria-label="Permalink to &quot;Manage your cookie preferences&quot;">​</a></h2><p><strong>Learn More and Customize</strong> in the cookie notice opens the <strong>Your Cookie Consent Preferences</strong> page. There, shoppers tick the kinds of cookies they agree to and click <strong>Save and Continue</strong>. Shoppers have to be signed in to open this page, so a guest is asked to sign in first. <strong>Manage Your Cookie Preferences</strong> holds the description shown beside each checkbox.</p><ol><li>Go to <strong>Configure &gt;&gt; General &gt;&gt; GDPR</strong>.</li><li>In <strong>Manage Your Cookie Preferences</strong>, edit the descriptions described in the table.</li><li>Click <strong>Save Configuration</strong>.</li></ol><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Strictly Necessary</strong></td><td>Describes the cookies the storefront needs in order to work. Its default text is the agreement sentence <em>I agree with the terms and conditions.</em>, so replace it with a description of these cookies.</td></tr><tr><td><strong>Basic Interactions &amp; Functionalities</strong></td><td>Describes the trackers behind basic interactions and features.</td></tr><tr><td><strong>Experience Enhancements</strong></td><td>Describes the trackers that personalize the shopper&#39;s experience.</td></tr><tr><td><strong>Measurements</strong></td><td>Describes the trackers that measure traffic and behavior.</td></tr><tr><td><strong>Targeting &amp; Advertising</strong></td><td>Describes the trackers used for personalized marketing and ads.</td></tr></tbody></table>',5))])}const k=r(g,[["render",c]]);export{f as __pageData,k as default};
